-- ============================================================
-- 007_padron_seed.sql
--
-- Setter inn hele Padrón-katalogen (helt nytt merke i databasen).
-- Hierarki: manufacturer -> brand -> series -> vitola.
-- Kilde: padron.com (offisielle vitola-lister, ring gauge/lengde,
-- aldring og Cigar Aficionado "Cigar of the Year"-historikk).
--
-- Serier:
--   1) Padron Series      (15 vitolas — grunnlinjen fra 1964)
--   2) Damaso              (6 vitolas — mildeste linje, Ecuador Connecticut)
--   3) 1926 Serie          (10 vitolas — boxpresset, 5 års aldring)
--   4) 1964 Anniversary    (16 vitolas — boxpresset, 4 års aldring)
--   5) Family Reserve      (7 vitolas — 10 års aldring, toppserie)
--
-- Totalt 54 nye rader. Ingen eksisterende rader berøres.
-- ============================================================

-- ----------------------------------------------------------------
-- 1) Padron Series
-- ----------------------------------------------------------------

-- ----------------------------------------------------------------
-- 2) Damaso Series
-- ----------------------------------------------------------------

-- ----------------------------------------------------------------
-- 3) 1926 Serie
-- ----------------------------------------------------------------

-- ----------------------------------------------------------------
-- 4) 1964 Anniversary Series
-- ----------------------------------------------------------------

-- ----------------------------------------------------------------
-- 5) Family Reserve
-- ----------------------------------------------------------------

-- ----------------------------------------------------------------
-- 6) ALIAS — vanlige skrivemåter/forkortelser for OCR/søk-treff
-- ----------------------------------------------------------------

-- ----------------------------------------------------------------
-- 7) Sanity check — skal være nøyaktig 54 nye Padron-rader
-- ----------------------------------------------------------------
do $$
declare
  cnt int;
begin
  select count(*) into cnt from cigars where manufacturer = 'Padron';
  if cnt <> 54 then
    raise exception 'Forventet 54 Padron-rader, fant %', cnt;
  end if;
end $$;
